 'Too many requests. Please try later.':{uz:'So‘rovlar limiti tugadi, birozdan so‘ng urinib ko‘ring.',ru:'Слишком много запросов. Повторите позже.'},
 'Internal server error':{uz:'Serverda xato yuz berdi. Terminaldagi xabarni tekshiring.',ru:'Ошибка сервера. Проверьте терминал.'},
 'You do not have permission to this booking':{uz:'Bu bronni tasdiqlashga ruxsat yo‘q.',ru:'Нет доступа к бронированию.'},
