function aiErrorText(err){
 const key=(err?.message||'').trim();
 const msg={
 uz:{AI_QUOTA_EXCEEDED:'Gemini bepul so‘rovlar limiti tugagan. Birozdan so‘ng qayta urinib ko‘ring.',AI_KEY_OR_PERMISSION:'Gemini API kaliti yoki loyiha ruxsatini tekshiring. Kalitni chatda ulashmang.',AI_MODEL_UNAVAILABLE:'Gemini hisobida ishlaydigan model topilmadi. .env faylidagi GEMINI_MODEL qiymatini tekshiring.',AI_PROVIDER_TEMPORARY:'Gemini xizmati vaqtincha mavjud emas. Keyinroq urinib ko‘ring.',AI_NETWORK_ERROR:'Internet yoki Gemini serveriga ulanishda muammo.',AI_EMPTY_RESPONSE:'Gemini bo‘sh javob qaytardi. Savolni boshqacha yozing.',AI_REQUEST_FAILED:'Gemini so‘rovni qabul qilmadi.', 'AI is not configured':'Gemini API kaliti serverda sozlanmagan.'},
 en:{AI_QUOTA_EXCEEDED:'Gemini request quota reached. Please try again later.',AI_KEY_OR_PERMISSION:'Check your Gemini API key and project permissions.',AI_MODEL_UNAVAILABLE:'No supported Gemini model is available for this account.',AI_PROVIDER_TEMPORARY:'Gemini is temporarily unavailable.',AI_NETWORK_ERROR:'Unable to connect to Gemini. Check the network.',AI_EMPTY_RESPONSE:'Gemini returned no answer; please rephrase.',AI_REQUEST_FAILED:'Gemini rejected the request.','AI is not configured':'Gemini API key is not configured on the server.'},
 ru:{AI_QUOTA_EXCEEDED:'Лимит запросов Gemini исчерпан. Повторите позже.',AI_KEY_OR_PERMISSION:'Проверьте API-ключ Gemini и разрешения проекта.',AI_MODEL_UNAVAILABLE:'Для аккаунта нет доступной модели Gemini.',AI_PROVIDER_TEMPORARY:'Сервис Gemini временно недоступен.',AI_NETWORK_ERROR:'Не удалось подключиться к Gemini.',AI_EMPTY_RESPONSE:'Gemini не ответил. Переформулируйте вопрос.',AI_REQUEST_FAILED:'Gemini отклонил запрос.','AI is not configured':'API-ключ Gemini не настроен на сервере.'}
 };return msg[state.lang]?.[key] || (state.config.aiEnabled?tr('aiError'):tr('aiUnavailable'));
}
// Streams actual Gemini output over a same-origin Server-Sent Events (SSE) POST.
// A visible incremental fallback is used only when streaming is unavailable.
const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
function updateAiBubble(index,bot){
  const el=document.querySelector(`[data-chat-index="${index}"]`);
  if(!el)return;
  if(el.classList.contains('thinking')){
    const replacement=document.createElement('p');replacement.className='bubble assistant streaming';
    replacement.dataset.chatIndex=String(index);el.replaceWith(replacement);
    replacement.textContent=bot.text;
  }else{el.textContent=bot.text;el.classList.add('streaming')}
  const scroll=$('#ai-messages');if(scroll)scroll.scrollTop=scroll.scrollHeight;
}
async function animateAiText(index,bot,answer){
  // Fallback is clearly local reveal, not claimed to be streamed model tokens.
  const segments=String(answer||'').match(/.{1,5}/gs)||[];
  for(const segment of segments){bot.text+=segment;updateAiBubble(index,bot);await delay(19)}
}
async function readAiStream(message,index,bot){
  const response=await fetch('/api/ai/stream',{
    method:'POST',credentials:'same-origin',
    headers:{'Content-Type':'application/json','Accept':'text/event-stream','X-Turagent-Request':'1',...(state.csrf?{'X-CSRF-Token':state.csrf}:{})},
    body:JSON.stringify({message})
  });
  if(!response.ok){const info=await response.json().catch(()=>({}));throw Error(info.error||'AI_REQUEST_FAILED')}
  if(!response.body)throw Error('STREAM_UNSUPPORTED');
  const reader=response.body.getReader(),decoder=new TextDecoder();
  let buffer='',done=false,received=false;
  while(!done){const part=await reader.read();if(part.done)break;buffer+=decoder.decode(part.value,{stream:true});
    const events=buffer.split('\n\n');buffer=events.pop()||'';
    for(const packet of events){for(const line of packet.split('\n')){
      if(!line.startsWith('data:'))continue;
      let event;try{event=JSON.parse(line.slice(5).trim())}catch{continue}
      if(event.delta){bot.text+=event.delta;received=true;updateAiBubble(index,bot)}
      if(event.error)throw Error(event.error);
      if(event.done)done=true;
    }}
  }
  if(!received&&!bot.text.trim())throw Error('AI_EMPTY_RESPONSE');
}
async function askAi(message){
  const msg=String(message||'').trim();if(!msg||state.aiThinking)return;
  state.aiThinking=true;state.chat.push({who:'user',text:msg});
  const bot={who:'assistant',text:'',thinking:true,streaming:true};state.chat.push(bot);
  const index=state.chat.length-1;renderChatWidget();
  try{
    const key=(aiExamples[state.lang]||aiExamples.uz).indexOf(msg);
    if(key>=0){await delay(240);await animateAiText(index,bot,(aiExampleAnswers[state.lang]||aiExampleAnswers.uz)[key])}
    else{
      try{await readAiStream(msg,index,bot)}
      catch(error){
        // Old deployments can still use the existing JSON endpoint as a safe fallback.
        if(['STREAM_UNSUPPORTED','AI_EMPTY_RESPONSE'].includes(error.message) && !bot.text){
          const result=await call('/api/ai/chat',{message:msg});await animateAiText(index,bot,result.answer||'')
        }else throw error;
      }
    }
  }catch(error){if(!bot.text)bot.text=aiErrorText(error);else bot.text+='\n'+aiErrorText(error)}
  finally{bot.thinking=false;bot.streaming=false;state.aiThinking=false;renderChatWidget()}
}
// Professional custom select presentation with native form values and keyboard fallback.
function enhanceSelects(){document.querySelectorAll('select:not([data-ui-enhanced])').forEach(select=>{select.dataset.uiEnhanced='1';const wrap=document.createElement('span');wrap.className='select-ui';select.parentNode.insertBefore(wrap,select);wrap.append(select);const button=document.createElement('button');button.type='button';button.className='select-ui-button';button.setAttribute('aria-haspopup','listbox');button.setAttribute('aria-label',select.getAttribute('aria-label')||select.closest('label')?.querySelector('b')?.textContent||'Select');button.setAttribute('aria-expanded','false');button.innerHTML=`<span>${esc(select.selectedOptions[0]?.text||'')}</span><span class="select-chevron" aria-hidden="true">${Icon('chevron',17)}</span>`;const menu=document.createElement('div');menu.className='select-ui-menu';menu.setAttribute('role','listbox');menu.hidden=true;function close(){menu.hidden=true;wrap.classList.remove('open');button.setAttribute('aria-expanded','false')};button.addEventListener('click',(e)=>{e.preventDefault();document.querySelectorAll('.select-ui.open').forEach(w=>{if(w!==wrap){w.classList.remove('open');w.querySelector('.select-ui-menu').hidden=true;w.querySelector('.select-ui-button').setAttribute('aria-expanded','false')}});menu.hidden=!menu.hidden;wrap.classList.toggle('open',!menu.hidden);button.setAttribute('aria-expanded',String(!menu.hidden));if(!menu.hidden){const rect=button.getBoundingClientRect();wrap.classList.toggle('drop-up',window.innerHeight-rect.bottom<270&&rect.top>270);menu.querySelector('[aria-selected=true]')?.focus()}});select.querySelectorAll('option').forEach(option=>{const o=document.createElement('button');o.type='button';o.className='select-ui-option';o.setAttribute('role','option');o.setAttribute('aria-selected',String(option.selected));o.textContent=option.text;o.addEventListener('click',()=>{select.value=option.value;button.querySelector('span').textContent=option.text;menu.querySelectorAll('.select-ui-option').forEach(x=>x.setAttribute('aria-selected',String(x===o)));close();select.dispatchEvent(new Event('change',{bubbles:true}))});o.addEventListener('keydown',e=>{const opts=[...menu.querySelectorAll('.select-ui-option')];let i=opts.indexOf(o);if(e.key==='ArrowDown'){e.preventDefault();opts[(i+1)%opts.length].focus()}if(e.key==='ArrowUp'){e.preventDefault();opts[(i-1+opts.length)%opts.length].focus()}if(e.key==='Escape'){close();button.focus()}});menu.append(o)});wrap.append(button,menu);select.tabIndex=-1;wrap.addEventListener('focusout',e=>{if(!wrap.contains(e.relatedTarget))close()})})}
document.addEventListener('pointerdown',e=>{document.querySelectorAll('.select-ui.open').forEach(w=>{if(!w.contains(e.target)){w.classList.remove('open');w.querySelector('.select-ui-menu').hidden=true;w.querySelector('.select-ui-button').setAttribute('aria-expanded','false')}})});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.select-ui.open').forEach(w=>{w.classList.remove('open');w.querySelector('.select-ui-menu').hidden=true;w.querySelector('.select-ui-button').setAttribute('aria-expanded','false')})});
document.addEventListener('input',e=>{if(e.target.matches('input[inputmode="numeric"]')){const previous=e.target.value;const updated=previous.replace(/[^0-9]/g,'');if(updated!==previous)e.target.value=updated}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form).entries());try{if(form.id==='hero-search'){state.filter.dest=data.destination;state.filter.days=data.days||'';state.search.date=data.date;state.search.people=Number(data.people);location.hash='#/tours?dest='+encodeURIComponent(data.destination||'');paint(true);return}if(form.id==='auth-form'){if(data.mode==='register'&&data.password!==data.confirm)throw Error(tr('confirmPassword'));const path=data.mode==='register'?'/api/register':data.mode==='forgot'?'/api/reset/request':data.mode==='reset'?'/api/reset/complete':'/api/login';const payload=data.mode==='reset'?{token:qparams().get('token'),password:data.password}:data;const res=await call(path,payload);if(data.mode==='forgot'){showToast(res.mailConfigured?tr('resetSent'):(state.lang==='uz'?'Email yuborish xizmati hali ulanmagan.':state.lang==='ru'?'Сервис отправки писем пока не подключён.':'Email delivery is not configured yet.'));return}if(data.mode==='reset'){routeTo('login');return}state.csrf=res.csrf;await refresh();routeTo('account');return}if(form.id==='newsletter-form'){await call('/api/newsletter',{email:data.email});form.reset();showToast(tr('subscribed'));return}if(form.id==='contact-form'||form.id==='service-form'){const isService=form.id==='service-form';await call('/api/inquiries',{kind:isService?'service':'contact',service:isService?state.editing?.service||'':'',name:data.name,email:data.email,message:data.message});state.editing=null;paint();showToast(tr('sent'));return}if(form.id==='profile-form'){await call('/api/profile',{name:data.name});await refresh();paint();showToast(tr('save'));return}if(form.id==='ai-form'){await askAi(data.message);return}if(form.id==='admin-tour-form'){const keys=['uz','en','ru'];const obj={id:data.id,title:Object.fromEntries(keys.map(k=>[k,data['title_'+k]])),city:Object.fromEntries(keys.map(k=>[k,data['city_'+k]])),desc:Object.fromEntries(keys.map(k=>[k,data['desc_'+k]])),destination:data.destination,price:Number(data.price),days:Number(data.days),image:data.image,type:data.type,discount:Number(data.discount),active:!!form.elements.active.checked};await call('/api/admin/tours',obj);state.editing=null;await refreshCatalog();adminLoad();return}if(form.id==='admin-post-form'){const keys=['uz','en','ru'];const obj={id:data.id,title:Object.fromEntries(keys.map(k=>[k,data['title_'+k]])),summary:Object.fromEntries(keys.map(k=>[k,data['summary_'+k]])),body:Object.fromEntries(keys.map(k=>[k,data['body_'+k]])),image:data.image,date:today(),read:5};await call('/api/admin/posts',obj);state.editing=null;await refreshCatalog();adminLoad();return}}catch(err){showToast(err.message)}});
console.info('Translation audit:',auditLanguages());load();
